activities.codeSnippet:
public class ArrayInitDemo {
    public static void main(String[] args) {
        // 1. Dynamic allocation with default zeros
        int[] counters = new int[3];
        System.out.println("Default int element: " + counters[0]); // 0

        // 2. Inline literal initialization
        String[] topStudents = {"Alex", "Beatrice", "Carlos", "Diana"};
        System.out.println("First student: " + topStudents[0]);
        System.out.println("Total students: " + topStudents.length);

        // 3. String array with default nulls
        String[] pendingOrders = new String[2];
        System.out.println("Default String element: " + pendingOrders[0]); // null
    }
}

