practiceProblems.solutionCode:
public class Main {
    public static void printFirstAndLast(double[] values) {
        System.out.println("Start: " + values[0] + " | End: " + values[values.length - 1]);
    }

    public static void main(String[] args) {
        printFirstAndLast(new double[]{1.5, 2.8, 4.2});
    }
}

